// Worker entry point: OpenNext serves HTTP; this adds the scheduled handler
// for ServerOS disconnect detection and data-retention pruning.
// @ts-expect-error -- generated by `opennextjs-cloudflare build`
import { default as openNext } from "./.open-next/worker.js";
import type { AppContext } from "./src/lib/context";
import { runScheduledMaintenance } from "./src/modules/serveros/sweep";

export default {
  fetch: openNext.fetch,
  async scheduled(_event: ScheduledController, env: CloudflareEnv, ctx: ExecutionContext) {
    const appCtx: AppContext = {
      db: env.DB,
      bucket: env.ASSETS_BUCKET,
      env,
      now: () => Date.now(),
      ip: null,
      userAgent: "cron",
      waitUntil: (p) => ctx.waitUntil(p),
    };
    ctx.waitUntil(runScheduledMaintenance(appCtx));
  },
} satisfies ExportedHandler<CloudflareEnv>;
